## Why This Is Asked
Tests ability to design a compact, efficient dynamic interval structure using classic DS tools (Fenwick, coordinate compression) and to reason about duplicates and point/range queries.

## Key Concepts
- Range update, point query via Fenwick trees
- Two-BIT technique for range add + range sum
- Coordinate compression for discrete integer endpoints
- Handling duplicates by counting multiplicities

## Code Example
```javascript
class Fenwick { constructor(n){ this.n=n; this.f=new Array(n+2).fill(0); } add(i,d){ for(;i<=this.n;i+=i&-i) this.f[i]+=d; } sum(i){ let s=0; for(;i>0;i-=i&-i) s+=this.f[i]; return s; } }
class IntervalDS {
  constructor(coords){
    this.coords = Array.from(new Set(coords)).sort((a,b)=>a-b);
    this.idx = new Map(this.coords.map((v,i)=>[v,i+1]));
    this.n = this.coords.length+2;
    this.B1 = new Fenwick(this.n);
    this.B2 = new Fenwick(this.n);
  }
  _upd(l,r,sign){ const L=this.idx.get(l); const R=this.idx.get(r+1); this.B1.add(L,sign); this.B1.add(R,-sign); this.B2.add(L,sign*(l-1)); this.B2.add(R,-sign*r); }
  insert(l,r){ this._upd(l,r,1); }
  erase(l,r){ this._upd(l,r,-1); }
  _pref(p){ // largest coord <= p
    let i = 0; // placeholder for upper_bound on this.coords
    // implement as needed in real code
    return this.B1.sum(i)*p - this.B2.sum(i);
  }
  countCover(x){ return this._pref(x) - this._pref(x-1); }
  coverageInRange(a,b){ return this._pref(b) - this._pref(a-1); }
}
```

## Follow-up Questions
- How would you adapt to online queries without pre-known coordinates?
- What are memory/time trade-offs if coordinates are dense vs sparse?

## Why This Is Asked
Assesses practical use of an augmented BST (treap) to support ranking with duplicates in a live leaderboard setting.

## Key Concepts
- Treap with random priorities for balancing
- Node augmentation: subtree size for rank queries
- Key design: (score, playerId) to distinguish duplicates
- Rank query logic traversing by score threshold
- Handling time-evolving duplicates safely

## Code Example
```javascript
class LeaderboardTreap {
  constructor() { this.root = null; }
  _cmp(a, b) {
    if (a.score !== b.score) return a.score - b.score;
    return a.playerId.localeCompare(b.playerId);
  }
  _size(n) { return n ? n.size : 0; }
  _update(n) { if (n) n.size = 1 + this._size(n.left) + this._size(n.right); }
  _rotateLeft(p) {
    const r = p.right; p.right = r.left; r.left = p; this._update(p); this._update(r); return r;
  }
  _rotateRight(p) {
    const l = p.left; p.left = l.right; l.right = p; this._update(p); this._update(l); return l;
  }
  insertScore(playerId, score) {
    const key = { playerId, score, __prio: Math.random() };
    this.root = this._insert(this.root, key);
  }
  _insert(n, key) {
    if (!n) return { key, priority: key.__prio, left: null, right: null, size: 1 };
    if (this._cmp(key, n.key) < 0) {
      n.left = this._insert(n.left, key);
      if (n.left.priority > n.priority) n = this._rotateRight(n);
    } else {
      n.right = this._insert(n.right, key);
      if (n.right.priority > n.priority) n = this._rotateLeft(n);
    }
    this._update(n); return n;
  }
  eraseScore(playerId, score) {
    const key = { playerId, score };
    this.root = this._erase(this.root, key);
  }
  _erase(n, key) {
    if (!n) return null;
    const c = this._cmp(key, n.key);
    if (c < 0) { n.left = this._erase(n.left, key); }
    else if (c > 0) { n.right = this._erase(n.right, key); }
    else {
      if (!n.left) return n.right;
      if (!n.right) return n.left;
      if (n.left.priority > n.right.priority) { n = this._rotateRight(n); n.right = this._erase(n.right, key); }
      else { n = this._rotateLeft(n); n.left = this._erase(n.left, key); }
    }
    this._update(n); return n;
  }
  getRank(score) {
    const dfs = (n) => {
      if (!n) return 0;
      if (n.key.score <= score) return this._size(n.left) + 1 + dfs(n.right);
      return dfs(n.left);
    };
    return dfs(this.root);
  }
}
```

## Follow-up Questions
- How would you adapt this to support getKRank(score, k) for the top-k ranks?
- What are trade-offs compared to using a Fenwick tree with coordinate compression for fixed score ranges?

